KEY=[('xAI Colossus (Memphis TN / Southaven MS)','colossus|southaven|solaris'),('OpenAI/Oracle Stargate Abilene TX (Lancium/Crusoe)','lancium|stargate'),('Crusoe (any)','crusoe'),('Meta Hyperion LA (Franklin Farms / Laidley)','franklin farms|laidley'),('Fermi America Matador TX','fermi america'),('GW Ranch / Pacifico TX','gw ranch|pacifico gw'),('Kilby TX','kilby'),('Poolside Pecos TX','poolside'),('Cipher Mining / Barber Lake TX','cipher mining|barber lake|black pearl'),('Core Scientific','core scientific'),('Galaxy Helios TX','galaxy'),('Riot / Whinstone / Corsicana TX','riot platforms|whinstone'),('Vantage Frontier / Shackelford TX','vantage frontier'),('Project Jupiter / BorderPlex NM (Acoma)','project jupiter|borderplex'),('Williams Socrates OH','socrates'),('Microsoft Fairwater WI/GA','fairwater'),('Amazon Rainier / New Carlisle IN','new carlisle'),('Gable Corp (Google) IA','gable corp'),('Sidecat (Meta) OH','sidecat'),('Tallgrass / Wyoming Hyperscale / Prometheus WY','wyoming hyperscale|prometheus hyperscale'),('VoltaGrid / ProEnergy (BTM gensets)','voltagrid|proenergy'),('Bloom Energy fuel cells','bloom energy'),('CoreWeave / Nebius / Fluidstack / Lambda','coreweave|nebius|fluidstack'),('Applied Digital Ellendale ND','applied digital|polaris forge'),('TeraWulf Lake Mariner NY','terawulf|lake mariner'),('Hut 8 River Bend LA','hut 8'),('Greenidge NY','greenidge'),('Sandow Lakes TX','sandow lakes'),('Related Digital / SB Energy (Stargate MI/TX)','related digital|sb energy'),('Behind-the-meter phrase','behind[- ]the[- ]meter'),('Private use network phrase','private use network')]
rows=[]
for lab,pat in KEY:
    rx=re.compile(pat)
    hit=[d for d,cc in cur.items() if any(rx.search(t) for t in cc)]
    inu=[d for d in hit if d in j.index]; mt=[d for d in inu if pd.notna(j.loc[d,'site_match'])]
    rows.append({'project':lab,'pattern':pat,'corpus_docs':len(hit),'union_docs':len(inu),'site_matched_docs':len(mt),'examples':'; '.join(hit[:4])})
pd.DataFrame(rows).to_csv(f'{OUT}/known_project_name_recall.csv',index=False)
